await expect(yStepperInputRefreshed).toBeVisible();
const yStepperDebug = await yStepperInputRefreshed.evaluate((el: HTMLInputElement) => ({
  tagName: el.tagName,
  type: el.type,
  value: el.value,
  readOnly: el.readOnly,
  disabled: el.disabled,
  id: el.id,
  hasFocus: document.activeElement === el,
}));
